"""Fund slot formulas generated by scripts/generate_ul_fund_slots.py."""

from avk.model.lang import Component, if_, on, param, prev, scen

SLOTS = 5


class FundSlots(Component):
    """Per-slot unit fund formulas and their policy totals."""

    REQUIRES = (
        "A_begin",
        "R_survival",
        "active_retention",
        "additions_pp",
        "allocated_pp",
        "live",
        "maturity",
        "rpu_retention",
        "to_rpu",
        "year_start",
    )
    fund_return_margin = param("fund_return_margin")
    mc_fund_return_source = param("mc_fund_return_source")
    reference_forward = scen("reference_forward")
    ret_eq_large = scen("ret_eq_large")
    ret_eq_mid = scen("ret_eq_mid")
    ret_eq_small = scen("ret_eq_small")
    ret_eq_global = scen("ret_eq_global")
    ret_gov_long = scen("ret_gov_long")
    ret_gov_short = scen("ret_gov_short")
    ret_corp_bond = scen("ret_corp_bond")
    ret_money_market = scen("ret_money_market")
    ret_gold = scen("ret_gold")
    ret_real_assets = scen("ret_real_assets")

    def fund_return_factor(self, t):
        """Monthly factor for the signed reserving fund return margin."""
        return (1 + self.fund_return_margin) ** (1 / 12)

    def rebalance(self, t):
        """Rebalance at the start of the policy year when target weights exist."""
        return self.policy.V_auto_rebalance and self.year_start(t) and self.allocation_total(t) > 0

    def fund_1_allocation(self, t):
        """Fund 1's share of the allocation weights."""
        return if_(
            self.allocation_total(t) > 0,
            self.policy.Fund_1_Allocation / self.allocation_total(t),
            0,
        )

    def fund_1_open(self, t):
        """Opening active value of slot 1, with rebalancing when due."""
        return if_(
            t == 0 or ((self.live(t) or self.maturity(t)) and self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.fund_close_total, 0) * self.fund_1_allocation(t),
                prev(
                    self.fund_1_close,
                    self.policy.Fund_1_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_1_after_premium(self, t):
        """Slot 1 after crediting its share of allocated premiums."""
        return self.fund_1_open(t) + self.allocated_pp(t) * self.fund_1_allocation(t)

    def fund_1_after_charges(self, t):
        """Slot 1 after its share of withdrawals and charges."""
        return self.fund_1_after_premium(t) * self.active_retention(t)

    def fund_1_market_return(self, t):
        """Monthly asset-mix return and fund alpha of slot 1."""
        return (
            self.policy.Fund_1_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_1_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_1_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_1_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_1_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_1_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_1_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_1_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_1_W_gold * self.ret_gold[t]
            + self.policy.Fund_1_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_1_Alpha) ** (1 / 12) - 1)

    def fund_1_growth_rate(self, t):
        """Gross investment return for slot 1."""
        return self.fund_1_market_return(t) * self.live(t)

    @on("reserving", overrides="fund_1_growth_rate")
    def fund_1_reserving_growth_rate(self, t):
        """Slot 1's return including the reserving margin."""
        return ((1 + self.fund_1_market_return(t)) * self.fund_return_factor(t) - 1) * self.live(t)

    @on("mc", overrides="fund_1_growth_rate")
    def fund_1_mc_growth_rate(self, t):
        """Slot 1's certainty-equivalent or scenario-driven return."""
        return if_(
            self.mc_fund_return_source == 0,
            self.reference_forward[t],
            self.fund_1_market_return(t),
        ) * self.live(t)

    def fund_1_additions(self, t):
        """Slot 1's share of the active anniversary additions."""
        return self.additions_pp(t) * if_(
            self.fund_after_charges_total(t) > 0,
            self.fund_1_after_charges(t) / self.fund_after_charges_total(t),
            self.fund_1_allocation(t),
        )

    def fund_1_grown(self, t):
        """Active slot 1 after growth, before its fund management charge."""
        return (self.fund_1_after_charges(t) + self.fund_1_additions(t)) * (
            1 + self.fund_1_growth_rate(t)
        )

    def fund_1_fmc_rate(self, t):
        """Monthly fund management charge rate for slot 1."""
        return (1 - (1 - self.policy.Fund_1_FMC) ** (1 / 12)) * self.live(t)

    def fund_1_fmc(self, t):
        """Fund management charge for active slot 1."""
        return self.fund_1_grown(t) * self.fund_1_fmc_rate(t)

    def fund_1_close(self, t):
        """Closing active value of slot 1 before expected exits."""
        return self.fund_1_grown(t) - self.fund_1_fmc(t)

    def rpu_1_open(self, t):
        """Opening aggregate paid-up holding in slot 1."""
        return prev(self.rpu_1_close, self.policy.Fund_1_Value * (self.policy.Policy_Status == 2))

    def rpu_1_after_charges(self, t):
        """Paid-up slot 1 after its proportional share of charges."""
        return self.rpu_1_open(t) * self.rpu_retention(t)

    def rpu_1_grown(self, t):
        """Paid-up slot 1 after its own investment return."""
        return self.rpu_1_after_charges(t) * (1 + self.fund_1_growth_rate(t))

    def rpu_1_fmc(self, t):
        """Fund management charge for paid-up slot 1."""
        return self.rpu_1_grown(t) * self.fund_1_fmc_rate(t)

    def rpu_1_after_fmc(self, t):
        """Paid-up slot 1 after growth and all charges, before expected exits."""
        return self.rpu_1_grown(t) - self.rpu_1_fmc(t)

    def rpu_1_close(self, t):
        """Surviving paid-up slot 1 plus transfers from active units."""
        return self.rpu_1_after_fmc(t) * self.R_survival(t) + self.to_rpu(t) * self.fund_1_close(t)

